  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="index.html">
        <img class="brand-mark" src="assets/logo.svg" width="28" height="28" alt="">
        <span class="brand-name">Acme Storefront</span>
      </a>
      <button class="nav-toggle" type="button" aria-label="Menu" aria-expanded="false" aria-controls="site-nav">
        <span class="nav-toggle-bar"></span>
        <span class="nav-toggle-bar"></span>
        <span class="nav-toggle-bar"></span>
      </button>
      <nav class="site-nav" id="site-nav" aria-label="Main">
        <a class="nav-link" href="index.html">Home</a>
        <a class="nav-link" href="products.html" aria-current="page">Products</a>
        <a class="nav-link" href="pricing.html">Pricing</a>
        <a class="nav-link" href="orders.html">Orders</a>
        <a class="nav-link" href="about.html">About</a>
        <a class="nav-link" href="contact.html">Contact</a>
      </nav>
    </div>
  </header>

  <main>
    <div class="container page-head">
      <h1>Products</h1>
      <p class="lede">Everything we make, in one place.</p>
    </div>

    <section class="section">
      <div class="container">
        <h2 class="section-title">All products</h2>
        <div class="chips">
          <span class="chip is-active">All</span>
          <span class="chip">Lighting</span>
          <span class="chip">Desk</span>
          <span class="chip">Audio</span>
        </div>
        <div class="cards">
          <div class="card product">
            <span class="badge">New</span>
            <div class="card-thumb thumb-1"></div>
            <div class="card-body">
              <h3>Aurora Lamp</h3>
              <p>Soft gradient light for long evenings.</p>
              <div class="card-foot">
                <span class="price">$49</span>
                <a class="btn btn-secondary btn-sm" href="contact.html">Add to cart</a>
              </div>
            </div>
          </div>
          <div class="card product">
            <div class="card-thumb thumb-2"></div>
            <div class="card-body">
              <h3>Sunset Mug</h3>
              <p>Keeps coffee warm through a long meeting.</p>
              <div class="card-foot">
                <span class="price">$18</span>
                <a class="btn btn-secondary btn-sm" href="contact.html">Add to cart</a>
              </div>
            </div>
          </div>
          <div class="card product">
            <div class="card-thumb thumb-3"></div>
            <div class="card-body">
              <h3>Forest Desk Mat</h3>
              <p>A calm surface for a busy day.</p>
              <div class="card-foot">
                <span class="price">$32</span>
                <a class="btn btn-secondary btn-sm" href="contact.html">Add to cart</a>
              </div>
            </div>
          </div>
          <div class="card product">
            <span class="badge badge-sale">Sale</span>
            <div class="card-thumb thumb-4"></div>
            <div class="card-body">
              <h3>Orchid Notebook</h3>
              <p>Dot-grid pages for sketches and lists.</p>
              <div class="card-foot">
                <span class="price">$14</span>
                <a class="btn btn-secondary btn-sm" href="contact.html">Add to cart</a>
              </div>
            </div>
          </div>
          <div class="card product">
            <div class="card-thumb thumb-5"></div>
            <div class="card-body">
              <h3>Slate Noise-Cancelling Headphones</h3>
              <p>Quiet for the open-plan office.</p>
              <div class="card-foot">
                <span class="price">$129</span>
                <a class="btn btn-secondary btn-sm" href="contact.html">Add to cart</a>
              </div>
            </div>
          </div>
          <div class="card product">
            <div class="card-thumb thumb-6"></div>
            <div class="card-body">
              <h3>Citrus Plant Pot</h3>
              <p>Something green next to the monitor.</p>
              <div class="card-foot">
                <span class="price">$22</span>
                <a class="btn btn-secondary btn-sm" href="contact.html">Add to cart</a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <h2 class="section-title">Bundles</h2>
        <div class="bundles">
          <div class="card">
            <div class="card-body">
              <h3>Desk starter</h3>
              <p>Lamp, mat and mug. Everything for a new desk.</p>
              <div class="card-foot">
                <span class="price">$89</span>
                <a class="btn btn-primary btn-sm" href="contact.html">Add bundle</a>
              </div>
            </div>
          </div>
          <div class="card">
            <div class="card-body">
              <h3>Quiet corner</h3>
              <p>Headphones, notebook and plant pot.</p>
              <div class="card-foot">
                <span class="price">$149</span>
                <a class="btn btn-primary btn-sm" href="contact.html">Add bundle</a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <p>© 2026 Acme Storefront. Small things for busy desks.</p>
      <div class="footer-links">
        <a href="about.html">About</a>
        <a href="contact.html">Contact</a>
      </div>
    </div>
  </footer>

  <script src="js/app.js"></script>
</body>
</html>
/* Reset, typography and page layout. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-ink);
  background: var(--color-bg);
}

h1,
h2,
h3,
p,
ul,
ol,
dl,
dd,
figure {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: var(--color-brand);
}

[hidden] {
  display: none !important;
}

h1 {
  font-size: 36px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -0.02em;
}

h2 {
  font-size: 24px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.01em;
}

h3 {
  font-size: 17px;
  line-height: 1.3;
  font-weight: 700;
}

.container {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0 var(--space-5);
}

.section {
  padding: var(--space-7) 0 0;
}

.section-title {
  margin-bottom: var(--space-5);
}

.page-head {
  padding-top: var(--space-7);
}

.page-head .lede {
  max-width: 640px;
  margin-top: var(--space-3);
}

.lede {
  font-size: 18px;
  color: var(--color-muted);
}

.muted {
  color: var(--color-muted);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  border: 0;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

@media (max-width: 720px) {
  h1 {
    font-size: 28px;
  }

  h2 {
    font-size: 21px;
  }

  .container {
    padding: 0 var(--space-4);
  }

  .section,
  .page-head {
    padding-top: var(--space-6);
  }
}
/* Shared components: header, button, card, form, table, modal, and friends. */

/* Header */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-line);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 18px;
  font-weight: 800;
  color: var(--color-ink);
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: var(--space-1);
}

.nav-link {
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 600;
  color: var(--color-ink);
  text-decoration: none;
}

.nav-link:hover {
  background: var(--color-bg);
}

.nav-link[aria-current='page'] {
  color: var(--color-brand);
  background: var(--color-brand-tint);
}

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  cursor: pointer;
}

.nav-toggle-bar {
  display: block;
  width: 18px;
  height: 2px;
  margin: 4px auto;
  border-radius: 1px;
  background: var(--color-ink);
}

/* Button */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 18px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font: inherit;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.2;
  text-decoration: none;
  cursor: pointer;
}

.btn-primary {
  background: var(--color-brand);
  color: #ffffff;
}

.btn-primary:hover {
  background: var(--color-brand-dark);
}

.btn-secondary {
  background: var(--color-surface);
  color: var(--color-surface);
  border-color: var(--color-line);
}

.btn-secondary:hover {
  background: var(--color-bg);
}

.btn-sm {
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
}

.btn-lg {
  padding: 13px 24px;
  font-size: 16px;
}

.btn[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Card */

.card {
  position: relative;
  background: var(--color-surface);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.card-body {
  padding: var(--space-5);
}

.card-thumb {
  height: 120px;
  border-radius: 13px 13px 0 0;
}

.card h3 {
  margin-bottom: var(--space-2);
}

.card p {
  font-size: 15px;
  color: var(--color-muted);
}

.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-4);
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
}

